import fs from "fs";
import path from "path";

/** Per-post SVG cover (generated by scripts/images/make-covers.mjs); falls back to the given image. */
export function coverOr(slug: string, fallback: string): string {
  return fs.existsSync(path.join(process.cwd(), "public/images/blog", `${slug}.svg`))
    ? `/images/blog/${slug}.svg`
    : fallback;
}

/** Minimal list thumbnail (one big stat, no title) generated by scripts/images/make-cards.mjs. */
export function cardOr(slug: string, fallback: string): string {
  return fs.existsSync(path.join(process.cwd(), "public/images/blog/cards", `${slug}.svg`))
    ? `/images/blog/cards/${slug}.svg`
    : coverOr(slug, fallback);
}
